// CBET Fundamentals practice deck (v28). Original exam-style items mapped to the AAMI CBET outline. Data only.
LSA.deck({
  id: "cbet", name: "CBET Fundamentals", icon: "🔌",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "openstax-up2": ["OpenStax University Physics Volume 2", "https://openstax.org/books/university-physics-volume-2/pages/1-introduction"],
    "openstax-ap": ["OpenStax Anatomy and Physiology 2e", "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-introduction"],
    "hhs-hipaa": ["HHS: HIPAA for Professionals", "https://www.hhs.gov/hipaa/for-professionals/index.html"],
    "nist-csf": ["NIST Cybersecurity Framework", "https://www.nist.gov/cyberframework"],
    "healthit": ["HealthIT.gov (ONC)", "https://www.healthit.gov/"],
    "osha-elec": ["OSHA Electrical Safety", "https://www.osha.gov/electrical"],
    "cdc-precautions": ["CDC: Standard Precautions for All Patient Care", "https://www.cdc.gov/infection-control/hcp/standard-precautions/index.html"],
    "cms-cops": ["CMS Conditions of Participation", "https://www.cms.gov/medicare/health-safety-standards/conditions-participation-requirements"],
    "fda-advice": ["FDA Device Advice: Comprehensive Regulatory Assistance", "https://www.fda.gov/medical-devices/device-advice-comprehensive-regulatory-assistance"],
    "fda-safety": ["FDA Medical Device Safety", "https://www.fda.gov/medical-devices/medical-device-safety"],
    "fda-infusion": ["FDA: Infusion Pumps", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/infusion-pumps"],
    "fda-defib": ["FDA: External Defibrillators and AEDs", "https://www.fda.gov/medical-devices/cardiovascular-devices/external-defibrillators-aeds-and-public-access-defibrillation"],
    "fda-pulseox": ["FDA: Pulse Oximeters", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/pulse-oximeters"],
    "fda-vent": ["FDA: Ventilators and Accessories", "https://www.fda.gov/medical-devices/products-and-medical-procedures/ventilators"],
    "fda-ultrasound": ["FDA: Ultrasound Imaging", "https://www.fda.gov/radiation-emitting-products/medical-imaging/ultrasound-imaging"],
    "fda-digital": ["FDA Digital Health Center of Excellence", "https://www.fda.gov/medical-devices/digital-health-center-excellence"],
    "nfpa-99": ["NFPA 99, Health Care Facilities Code (cited, not pasted)", "https://www.nfpa.org/codes-and-standards/nfpa-99-standard-for-health-care-facilities"],
    "iec-60601": ["IEC 60601-1 (FDA recognized consensus standard page; cited, not pasted)", "https://www.fda.gov/medical-devices/standards-and-conformity-assessment-program/recognized-consensus-standards-recognized-consensus-standards"],
    "aami-cbet": ["AAMI: Certified Biomedical Equipment Technician (CBET) exam content outline", "https://aami.org/certifications/cbet/"],
  },
  cards: [
    { id: "cb001", ages: 'both', topic: "anatomy", s: "The primary job of the heart is to:", c: ["Filter waste from blood in the kidneys", "Pump blood through the circulatory system", "Exchange gases between air and blood", "Store bile from the liver in the gallbladder"], f: "The heart is a muscular pump that moves blood through the pulmonary and systemic circulations. Its primary job is to pump blood through the circulatory system.", keyTerm: "Pump blood through the circulatory system", src: "openstax-ap" },
    { id: "cb002", ages: 'both', topic: "anatomy", s: "Gas exchange between air and blood occurs mainly in the:", c: ["chambers of the heart", "alveoli of the lungs", "bronchi of the airways", "pulmonary arteries"], f: "Oxygen and carbon dioxide cross the alveolar-capillary membrane in the alveoli of the lungs. The left ventricle pumps oxygenated blood but does not perform that gas exchange.", keyTerm: "alveoli of the lungs", src: "openstax-ap" },
    { id: "cb003", ages: 'both', topic: "anatomy", s: "The brain is part of which system?", c: ["The digestive system", "The nervous system", "The urinary system", "The integumentary system"], f: "The brain, spinal cord, and nerves make up the nervous system, which coordinates sensation, control, and many automatic functions.", keyTerm: "The nervous system", src: "openstax-ap" },
    { id: "cb004", ages: 'both', topic: "anatomy", s: "Skin is the major organ of which system?", c: ["The respiratory system", "The integumentary system", "The skeletal system", "The endocrine system"], f: "Skin, hair, and associated glands form the integumentary system, a barrier that also helps with sensation and temperature control.", keyTerm: "The integumentary system", src: "openstax-ap" },
    { id: "cb005", ages: 'both', topic: "anatomy", s: "In medical terms, 'hypo-' as a prefix usually means:", c: ["Above or higher than normal, as in hypertension", "Below or lower than normal, as in hypotension", "Around or surrounding a structure, as in periosteum", "Against or opposed to a structure, as in contraindication"], f: "Hypo- means below or lower than normal, as in hypotension or hypoglycemia. Hyper- means above or excessive. Peri- means around. Contra- means against.", keyTerm: "Below or lower than normal, as in hypotension", src: "openstax-ap" },
    { id: "cb006", ages: 'both', topic: "anatomy", s: "Blood returns to the right atrium of the heart mainly through the:", c: ["aorta", "vena cava", "pulmonary veins", "pulmonary trunk"], f: "Systemic venous blood enters the right atrium by the vena cava. The aorta carries blood out of the left ventricle. Pulmonary veins return blood from the lungs to the left atrium.", keyTerm: "vena cava", src: "openstax-ap" },
    { id: "cb007", ages: 'both', topic: "anatomy", s: "The musculoskeletal system includes:", c: ["Lungs, airways, and alveoli for ventilation", "Bones, joints, and muscles for movement", "Liver, pancreas, and intestine for digestion", "Eyes, ears, and receptors for vision"], f: "Bones, joints, and muscles work together for movement, with cartilage adding support and protection. Lungs belong to the respiratory system.", keyTerm: "Bones, joints, and muscles", src: "openstax-ap" },
    { id: "cb008", ages: 'both', topic: "electricity", s: "A 12 V source drives 0.010 A through a resistor. What is the resistance? Use Ohm's law \\(V=IR\\).", c: ["0.12 ohm", "1200 ohm", "12 ohm", "120 ohm"], f: "Ohm's law rearranged is \\(R=V/I=12/0.010=1200\\) ohm. Using \\(V I\\) or forgetting the decimal in the current are common mistakes.", keyTerm: "1200 ohm", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A simple series circuit with a voltage source and resistors." },
    { id: "cb009", ages: 'both', topic: "electricity", s: "Two resistors, \\(2.0\\,\\mathrm{k}\\Omega\\) and \\(2.0\\,\\mathrm{k}\\Omega\\), are in series with a 10 V source. What is the current?", c: ["5.0 mA", "2.5 mA", "10 mA", "2.5 amperes"], f: "Series resistance is \\(2.0+2.0=4.0\\,\\mathrm{k}\\Omega\\). Current is \\(I=V/R=10/4000=0.0025\\,\\mathrm{A}=2.5\\,\\mathrm{mA}\\).", keyTerm: "2.5 mA", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A series circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb010", ages: 'both', topic: "electricity", s: "Two \\(100\\,\\Omega\\) resistors are in parallel on a 10 V source. What is the total current from the source?", c: ["0.10 A", "0.20 A", "0.05 A", "20 A"], f: "Each branch draws \\(10/100=0.10\\,\\mathrm{A}\\), so the source current is \\(0.20\\,\\mathrm{A}\\). Equivalently \\(R_{\\mathrm{eq}}=50\\,\\Omega\\) and \\(I=10/50=0.20\\,\\mathrm{A}\\).", keyTerm: "0.20 A", src: "openstax-up2", img: "img/cbet-parallel.svg", imgAlt: "A parallel circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb011", ages: 'both', topic: "electricity", s: "A device draws 2.0 A from a 24 V DC supply. What is the power?", c: ["12 W", "48 W", "26 W", "0.083 W"], f: "Electrical power is \\(P=VI=24(2.0)=48\\) W. Also \\(P=I^{2}R\\) or \\(V^{2}/R\\) once resistance is known.", keyTerm: "48 W", src: "openstax-up2" },
    { id: "cb012", ages: 'both', topic: "electricity", s: "A line isolation monitor (LIM) in a healthcare isolated power system is used to:", c: ["Warn of a branch-circuit overload or a short on an isolated panel", "Warn of leakage or a first fault to ground on an isolated panel", "Warn of a dropped phase or a low supply voltage on the isolated panel", "Warn of a patient-cable artifact or a loose lead on an isolated receptacle"], f: "In isolated power systems used in some critical care areas, a LIM watches for a first ground fault or excessive leakage and alarms so the fault can be found before a second fault occurs. That is a warning of leakage or a first fault to ground on an isolated panel. It is not an overcurrent device, a phase-loss relay, or a physiologic-monitor artifact alarm.", keyTerm: "of leakage or a first fault to ground on an isolated panel", src: "openstax-up2" },
    { id: "cb013", ages: 'both', topic: "electricity", s: "An uninterruptible power supply (UPS) is used mainly to:", c: ["Carry the hospital electrical load through a long outage", "Bridge a short utility outage until another source takes over", "Step building voltage as the facility main transformer", "Provide isolated power for a surgical-suite panel"], f: "A UPS is used to bridge a short utility outage until another source takes over, and often to provide clean power. It is not a generator for long outages, a facility transformer, or an isolated-power panel.", keyTerm: "Bridge a short utility outage until another source takes over", src: "openstax-up2" },
    { id: "cb014", ages: 'both', topic: "healthit", s: "Under HIPAA, a use of protected health information that is permitted without a separate patient authorization is:", c: ["Marketing, sale of PHI, or a vendor product demonstration", "Treatment, payment, or healthcare operations", "Employment screening, life-insurer underwriting, or a news-media request", "A public tour roster, a press interview, or a sales brochure"], f: "The HIPAA Privacy Rule permits use of PHI for treatment, payment, or healthcare operations without a separate authorization, subject to the minimum-necessary standard for many uses. Marketing, sale of PHI, employment screening, and media or public-tour uses generally need another legal basis or authorization.", keyTerm: "Treatment, payment, or healthcare operations", src: "hhs-hipaa", also: ["nist-csf"] },
    { id: "cb015", ages: 'both', topic: "healthit", s: "A unique hardware address burned into a network interface is called a:", c: ["An IPv4 host address", "A media-access-control (MAC) address", "A default-gateway address", "A wireless network name (SSID)"], f: "A media-access-control (MAC) address is a unique identifier stored in a network interface, often at the factory. Layer-3 numbers, next-hop routers, and wireless network names are assigned or configured in other layers.", keyTerm: "A media-access-control (MAC) address", src: "healthit", also: ["nist-csf"] },
    { id: "cb016", ages: 'both', topic: "healthit", s: "IPv4 address 192.168.1.20 is commonly used as:", c: ["A public address that is routable on the global Internet", "A private address not routable on the global Internet", "A link-local APIPA address in the 169.254.0.0/16 range", "A documentation address in the 192.0.2.0/24 TEST-NET range"], f: "RFC 1918 private address space is not forwarded by provider routers as a global destination. 192.168.1.20 sits in the 192.168.0.0/16 private block, so it is a private address not routable on the global Internet.", keyTerm: "A private address not routable on the global Internet", src: "healthit", also: ["nist-csf"] },
    { id: "cb017", ages: 'both', topic: "healthit", s: "The PING utility is used mainly to:", c: ["Copy a large file and gauge sustained path throughput", "Test whether a host is reachable and measure round-trip time", "Open a remote desktop session and change the host IP settings", "Scan the TCP ports and list the services on the host"], f: "PING sends ICMP echo requests and reports whether replies return, so you can test whether a host is reachable and measure round-trip time on the path. It is a basic network diagnostic, not a calibration or leakage-current tool.", keyTerm: "Test whether a host is reachable and measure round-trip time", src: "healthit", also: ["nist-csf"] },
    { id: "cb018", ages: 'both', topic: "healthit", s: "A medical device that cannot talk to the electronic medical record, even though the network is up, may have a problem with:", c: ["The display calibration on a physiologic monitor", "The interface middleware that maps clinical data to the EMR", "The wall receptacle on a monitor that is still running", "The nurse-call cable between the bed and the hall station"], f: "Device-to-EMR integration often uses a gateway or middleware, commonly with a standard such as HL7. A mapping, license, or interface-engine fault can block data even when the LAN is healthy, because the interface middleware that maps clinical data to the EMR is the failing step.", keyTerm: "The interface middleware that maps clinical data to the EMR", src: "healthit", also: ["nist-csf"] },
    { id: "cb019", ages: 'both', topic: "healthit", s: "NIST cybersecurity guidance for systems that handle sensitive data emphasizes:", c: ["The CIA triad as a complete named framework", "The six CSF functions from Govern through Recover", "A help-desk ticket workflow for device repair", "A one-time annual audit of access logs"], f: "NIST Cybersecurity Framework 2.0 organizes work into the six CSF functions from Govern through Recover (Govern, Identify, Protect, Detect, Respond, and Recover). Patching, access control, and monitoring support that structure.", keyTerm: "The six CSF functions", src: "nist-csf" },
    { id: "cb020", ages: 'both', topic: "healthit", s: "A workstation will not boot and the display stays dark, even on a known-good monitor. A useful early hardware check is to:", c: ["Reimage the PC and reload the enterprise software image", "Inspect the power supply and POST indicators", "Reinstall the video driver and check the display", "Reset the BIOS password and user settings"], f: "When a workstation will not boot and the display stays dark on a known-good monitor, a useful early hardware check is to inspect the power supply and POST indicators. Reimaging, video-driver work, or a BIOS-settings reset comes after basic power and POST checks.", keyTerm: "Inspect the power supply and POST indicators", src: "healthit", also: ["nist-csf"] },
    { id: "cb021", ages: 'both', topic: "healthit", s: "Applying OS and application patches on networked medical systems is important for this reason:", c: ["Delayed patching is mainly a documentation issue for surveyors", "Unpatched systems are a frequent path for malware", "A firewall is enough protection on a missed-patch host", "A future upgrade can take the place of current patches"], f: "Timely, tested patching reduces known vulnerabilities. Unpatched systems are a frequent path for malware, including ransomware and data breaches. Clinical systems still need a change process so a patch does not break a device or workflow.", keyTerm: "Unpatched systems are a frequent path for malware", src: "healthit", also: ["nist-csf"] },
    { id: "cb022", ages: 'both', topic: "healthit", s: "A wireless access point is used to:", c: ["Connect Wi-Fi clients directly to the public WAN", "Connect Wi-Fi clients to the wired facility network", "Route client traffic between campus subnets", "Terminate a site-to-site VPN tunnel for remote clinics"], f: "An access point is used to connect Wi-Fi clients to the wired facility network, and sometimes to bridge other APs to the LAN. Internet access, if any, still goes through the facility network and its routers. An AP is not a replacement for a core router or the site's only VPN gateway.", keyTerm: "Connect Wi-Fi clients to the wired facility network", src: "healthit", also: ["nist-csf"] },
    { id: "cb023", ages: 'both', topic: "healthit", s: "A switch, as opposed to a simple hub, typically:", c: ["Floods each arrival out the attached ports", "Forwards each frame to the correct port by MAC address", "Routes each packet to another subnet by IPv4 address", "Assigns each station a telephone extension in a PBX"], f: "A switch forwards each frame to the correct port by MAC address. A hub floods every frame. Inter-subnet routing is the job of a router or layer-3 device, and analog trunks belong to a PBX.", keyTerm: "Forwards each frame to the correct port by MAC address", src: "healthit", also: ["nist-csf"] },
    { id: "cb024", ages: 'both', topic: "healthit", s: "A default gateway is:", c: ["The DNS server address a host uses to resolve names", "The router address a host uses to reach other networks", "The MAC address a host uses on the local Ethernet segment", "The DHCP server address a host uses to lease an IPv4 address"], f: "If a destination is not on the local segment, the host sends packets to its default gateway, which then routes them onward. A default gateway is the router address a host uses to reach other networks.", keyTerm: "The router address a host uses to reach other networks", src: "healthit", also: ["nist-csf"] },
    { id: "cb025", ages: 'both', topic: "healthit", s: "Hardening a Windows PC used near a medical device should include:", c: ["Unique accounts, a long idle lock, and postponed monthly updates", "Unique accounts, a short auto-lock, and timely security updates", "Unique accounts, a shift-end logoff reminder, and quarterly updates", "Unique accounts, a manual lock prompt, and annual security updates"], f: "Unique credentials, a short auto-lock, and timely updates reduce the chance that an unattended session exposes PHI or device control. A basic hardening set is unique accounts, a short auto-lock, and timely security updates.", keyTerm: "a short auto-lock, and timely security updates", src: "healthit", also: ["nist-csf"] },
    { id: "cb026", ages: 'both', topic: "healthit", s: "A virtual server is:", c: ["An operating system installed directly on bare metal", "A guest operating system running on a hypervisor", "A container process that shares the host kernel", "A bootable firmware utility stored in the system ROM"], f: "A virtual server is a guest operating system running on a hypervisor. A bare-metal install sits on the hardware with no hypervisor layer, and firmware utilities in ROM are not guest servers.", keyTerm: "A guest operating system running on a hypervisor", src: "healthit", also: ["nist-csf"] },
    { id: "cb027", ages: 'both', topic: "healthit", s: "Cloud computing for a clinic means, at a basic level:", c: ["Keeping clinic servers in the facility's own closet", "Using computing resources over a network under a service model", "Moving clinic records into a closet on the same campus", "Using a vendor appliance inside the same facility"], f: "Cloud computing means using computing resources over a network under a service model, often off site. HIPAA still applies: a business associate agreement and security safeguards are needed when PHI is involved.", keyTerm: "Using computing resources over a network under a service model", src: "healthit", also: ["nist-csf"] },
    { id: "cb028", ages: 'both', topic: "healthit", s: "A cable tester or toner is most useful when you need to:", c: ["Check a cable during an electrical leakage test", "Verify continuity of a copper network run", "Calibrate a clinical analyzer from the toner signal", "Measure leakage current on a network drop"], f: "Testers and toners help prove a cable's identity, continuity, and sometimes pair mapping or length. They are used to verify continuity of a copper network run. They do not replace a safety analyzer or a clinical laboratory instrument.", keyTerm: "Verify continuity of a copper network run", src: "healthit", also: ["nist-csf"] },
    { id: "cb029", ages: 'both', topic: "healthit", s: "HHS has published cybersecurity performance goals for healthcare for this reason:", c: ["Billing delays are the main operational impact", "Clinical care can be disrupted by those attacks", "Vendor billing offices are the systems usually hit", "Community hospitals seldom see those attacks"], f: "Healthcare is a frequent ransomware and breach target. Clinical care can be disrupted by those attacks, and PHI can be exposed. Federal performance goals and HIPAA security requirements aim to keep systems available so care can continue.", keyTerm: "Clinical care can be disrupted", src: "healthit", also: ["nist-csf"] },
    { id: "cb030", ages: 'both', topic: "healthit", s: "A KVM switch is used to:", c: ["Feed several medical devices from one power receptacle", "Share one set of input devices among several computers", "Connect several infusion pumps through one serial cable", "Send nurse-call audio to a central monitoring station"], f: "A KVM switch is used to share one set of input devices among several computers, typically a keyboard, video display, and mouse. It is not a power strip, a serial sharer for pumps, or a nurse-call audio bridge.", keyTerm: "Share one set of input devices among several computers", src: "healthit", also: ["nist-csf"] },
    { id: "cb031", ages: 'both', topic: "function", s: "Korotkoff sounds are used when measuring:", c: ["Heart sounds with a stethoscope during a chest exam", "Blood pressure with a cuff during a clinical check", "Breath sounds with a stethoscope during a pulmonary exam", "Body temperature with a probe during a fever check"], f: "Korotkoff sounds are the noises heard while a cuff is deflated, and they are used to measure blood pressure with a cuff during a clinical check, often with a stethoscope or a simulator.", keyTerm: "Blood pressure with a cuff", src: "fda-advice" },
    { id: "cb032", ages: 'both', topic: "function", s: "Einthoven's triangle refers to:", c: ["Chest leads V1, V2, and V3 in the precordial set", "Limb leads I, II, and III of the standard ECG", "Augmented leads aVR, aVL, and aVF in the derived set", "Rhythm leads I, II, and III on a ward monitor"], f: "Einthoven's triangle is formed by limb leads I, II, and III of the standard ECG, placed on the right arm, left arm, and left leg. It is a basic ECG lead model, not a precordial-lead or safety-sign topic.", keyTerm: "Limb leads I, II, and III", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform showing P, QRS, and T waves." },
    { id: "cb033", ages: 'both', topic: "function", s: "On a normal ECG, the QRS complex mainly represents:", c: ["Atrial depolarization", "Ventricular depolarization", "Ventricular repolarization", "Atrial repolarization"], f: "The QRS complex mainly reflects ventricular depolarization, the large deflection that follows the small earlier wave and precedes the later recovery wave.", keyTerm: "Ventricular depolarization", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG waveform with the P wave, QRS complex, and T wave labeled.", imgAsk: true },
    { id: "cb034", ages: 'both', topic: "function", s: "A defibrillator analyzer is used to:", c: ["Measure leakage current on the defibrillator chassis", "Measure a defibrillator's output energy during a test", "Note the selected energy setting from the front panel", "Measure battery open-circuit voltage on the defibrillator"], f: "A defibrillator analyzer is used to measure a defibrillator's output energy during a test, often with charge time and a recorded waveform, by discharging into a known test load. Chassis safety checks belong on a different instrument, and a setting or supply reading is not a delivered-energy measurement.", keyTerm: "Measure a defibrillator's output energy during a test", src: "fda-defib" },
    { id: "cb035", ages: 'both', topic: "function", s: "An electrical safety analyzer is used to:", c: ["Measure ECG gain, SpO2 accuracy, and similar monitor points", "Measure leakage current, ground resistance, and similar chassis points", "Measure infusion rate, occlusion pressure, and similar pump points", "Measure defibrillator energy, pacing current, and similar therapy points"], f: "Safety analyzers measure leakage current, ground resistance, and similar chassis points against the limits in the applicable standard, for example IEC 60601 or a facility policy based on NFPA 99. Monitor, pump, and therapy output checks use other dedicated test equipment.", keyTerm: "Measure leakage current, ground resistance, and similar chassis points", src: "fda-safety" },
    { id: "cb036", ages: 'both', topic: "function", s: "A physiologic simulator is used to:", c: ["Provide a known therapeutic energy pulse to a defibrillator", "Provide a known electrical waveform to a bedside monitor", "Provide a known gas mixture to a laboratory analyzer", "Provide a known charge current to an implanted pacemaker"], f: "A physiologic simulator is used to provide a known electrical waveform to a bedside monitor so the display and alarms can be checked against a source of known value. Energy-output tests, cal-gas work, and implant support use other dedicated equipment.", keyTerm: "Provide a known electrical waveform to a bedside monitor", src: "fda-advice" },
    { id: "cb037", ages: 'both', topic: "function", s: "Blood pressure in the clinic is commonly reported in:", c: ["Millimeters of H2O (mmH2O)", "Millimeters of mercury (mmHg)", "Centimeters of mercury (cmHg)", "Centimeters of H2O (cmH2O)"], f: "Arterial blood pressure is measured in millimeters of mercury (mmHg). Lumens measure light, becquerel is activity, and siemens is conductance.", keyTerm: "Millimeters of mercury (mmHg)", src: "fda-advice" },
    { id: "cb038", ages: 'both', topic: "function", s: "A pulse oximeter estimates:", c: ["Venous oxygen saturation taken from a catheter blood sample in a vein", "Oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed", "End-tidal carbon dioxide taken from a sample of exhaled gas at the airway opening", "Inspired oxygen concentration taken from a gas-analysis cell in the circuit"], f: "Pulse oximetry estimates oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed, using at least two light wavelengths. EtCO2 is a capnography measurement, not the same sensor.", keyTerm: "Oxygen saturation in arterial blood from light absorbed by a", src: "fda-pulseox" },
    { id: "cb039", ages: 'both', topic: "function", s: "End-tidal CO2 (EtCO2) monitoring is used mainly to:", c: ["Follow oxygen concentration in inspired gas during anesthesia", "Follow carbon dioxide in exhaled gas during sedation", "Follow nitrogen concentration in a medical-gas manifold", "Follow agent concentration in a room-air sample"], f: "End-tidal monitoring is used to follow carbon dioxide in exhaled gas during sedation, as a breath-by-breath check of ventilation and of the airway.", keyTerm: "Follow carbon dioxide in exhaled gas during sedation", src: "fda-advice" },
    { id: "cb040", ages: 'both', topic: "function", s: "A telemetry system in a hospital is used to:", c: ["Print a single-lead ECG at the local station on a local writer", "Send physiologic waveforms from a mobile patient to a central station", "Show live camera video on a public waiting-room screen", "Attach scanned consent forms to a patient billing claim"], f: "Hospital telemetry is used to send physiologic waveforms from a mobile patient to a central station so a staffed station can watch the tracing while the person is not tied to a ward monitor.", keyTerm: "Send physiologic waveforms from a mobile patient to a central", src: "fda-digital" },
    { id: "cb041", ages: 'both', topic: "function", s: "An infusion pump (LVP or syringe) is designed to:", c: ["Deliver fluids or medications at a set temperature", "Deliver fluids or medications at a set rate", "Deliver fluids or medications in an unmetered bolus", "Deliver oxygen or air at a set wall flow"], f: "Infusion devices control rate and volume. Different types (large-volume, syringe, PCA, and injectors) fit different therapies, but the basic job is to deliver fluids or medications at a set rate.", keyTerm: "Deliver fluids or medications at a set rate", src: "fda-infusion" },
    { id: "cb042", ages: 'both', topic: "function", s: "A PCA pump is intended to:", c: ["Let a patient request extra maintenance-fluid boluses", "Let a patient request extra pain doses within programmed limits", "Let a nurse request additional ventilator breaths from the handset", "Let a clinician start an antibiotic infusion from the handset"], f: "Patient-controlled analgesia pumps give a programmed basal or demand dose with lockout limits, so they let a patient request extra pain doses within programmed limits.", keyTerm: "Let a patient request extra pain doses within programmed limits", src: "fda-infusion" },
    { id: "cb043", ages: 'both', topic: "function", s: "A ventilator is life-support equipment whose basic job is to:", c: ["Circulate blood on a cardiopulmonary bypass circuit in the OR", "Move air through the lungs of the patient during ventilation", "Warm the patient with a forced-air blanket in the recovery bay", "Monitor the ECG during transport to another unit"], f: "Ventilators deliver a set gas pattern so they can move air through the lungs of the patient during ventilation, when breathing needs help or replacement. They require trained use, alarms, and backup power. They are not simple monitors, and they do not move blood, ECG signals, or blanket heat.", keyTerm: "Move air through the lungs of the patient during ventilation", src: "fda-vent" },
    { id: "cb044", ages: 'both', topic: "function", s: "An external defibrillator is used to:", c: ["Deliver a shock for asystole", "Deliver a shock for ventricular fibrillation", "Deliver a shock for pulseless electrical activity", "Deliver a shock for a sinus rhythm with a pulse"], f: "Defibrillators treat shockable arrhythmias under clinical protocols. An external defibrillator is used to deliver a shock for ventricular fibrillation, and for pulseless ventricular tachycardia when that is the indicated rhythm.", keyTerm: "Deliver a shock for ventricular fibrillation", src: "fda-defib" },
    { id: "cb045", ages: 'both', topic: "function", s: "An electrosurgical unit (ESU) is used in the operating room to:", c: ["Ablate or divide tissue with a high-frequency ultrasound handpiece", "Cut or coagulate tissue with a high-frequency current", "Cut or ablate tissue using a surgical laser beam", "Dissect tissue using a high-pressure irrigating jet"], f: "ESUs deliver a high-frequency current through an active electrode, with a return path (monopolar) or between the tips (bipolar), to cut or coagulate tissue. Safe use depends on return-electrode integrity, accessories, and smoke control. An ESU is used to cut or coagulate tissue with a high-frequency current.", keyTerm: "high-frequency current", src: "fda-advice" },
    { id: "cb046", ages: 'both', topic: "safety", s: "Patient leakage current, as used in electrical safety testing of medical equipment, is:", c: ["Current found in the protective earth conductor during a protective-earth current test", "Current measured in an applied part connected to the patient circuit", "Current taken at the mains plug during a dielectric strength test", "Current obtained at a network port during a data-cable certification test"], f: "Patient leakage current is current measured in an applied part connected to the patient circuit. Protective-earth current, dielectric-strength tests, and data-cable checks are different measurements.", keyTerm: "Current measured in an applied part", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb047", ages: 'both', topic: "function", s: "An autoclave uses which combination as its basic killing method?", c: ["Dry heat at a documented time and temperature", "Saturated steam under pressure in a timed cycle", "A chemical wipe of the chamber at ambient conditions", "Ethylene oxide gas at a documented cycle"], f: "Steam sterilizers (autoclaves) use saturated steam under pressure in a timed cycle, often with a recorded load process. Other heat, gas, or wipe methods are different processes, not the basic autoclave cycle.", keyTerm: "Saturated steam under pressure", src: "fda-advice" },
    { id: "cb048", ages: 'both', topic: "function", s: "A laboratory centrifuge is used to:", c: ["Incubate a sample at a set temperature in a heating block", "Separate components of a sample by spinning the tube at speed", "Mix a sample by gentle agitation on a laboratory rocker for several minutes at a fixed temperature", "Cool a sample in a circulating bath to a stated temperature"], f: "Centrifuges spin samples so denser components move outward. They separate components of a sample by spinning the tube at speed. Imbalance, lid interlocks, and speed verification are typical safety and performance points.", keyTerm: "Separate components of a sample by spinning the tube at speed", src: "fda-advice" },
    { id: "cb049", ages: 'both', topic: "function", s: "A laboratory refrigerator or freezer is important for this reason:", c: ["It keeps reagents at ambient temperature for easier access", "It keeps reagents at the required storage temperature", "It stores opened sterile instrument packs until the next case", "It holds device batteries overnight for the shop"], f: "Lab cold storage is important because it keeps reagents at the required storage temperature, often with alarms and monitoring. Ambient holding, sterile-pack storage, and battery storage are not the reason for a laboratory refrigerator.", keyTerm: "It keeps reagents at the required storage temperature", src: "fda-advice" },
    { id: "cb050", ages: 'both', topic: "function", s: "An ultrasound imager forms pictures mainly by:", c: ["Sending radiofrequency pulses in a strong magnetic field", "Sending high-frequency sound to receive echoes", "Detecting gamma rays from an injected tracer", "Recording skin temperature with a thermal camera"], f: "Diagnostic ultrasound transmits pulses and listens for reflections, sending high-frequency sound to receive echoes. Other modalities use different energy sources, not pulse-echo sound.", keyTerm: "Sending high-frequency sound to receive echoes", src: "fda-ultrasound" },
    { id: "cb051", ages: 'both', topic: "function", s: "A digital multimeter (DVM) in a shop is used to:", c: ["Read patient leakage current on an applied part", "Measure a basic electrical quantity in a circuit", "Check defibrillator energy into a test load", "Check SpO2 accuracy with a finger phantom"], f: "A DVM is general test equipment. It is used to measure a basic electrical quantity in a circuit, such as voltage, current, or resistance. Use it on de-energized circuits where required, with the right function and range. It is not a substitute for a medical-grade safety analyzer or a physiologic simulator.", keyTerm: "Measure a basic electrical quantity in a circuit", src: "fda-advice" },
    { id: "cb052", ages: 'both', topic: "function", s: "An SCD (sequential compression device) is used to:", c: ["Apply a sequential chest vest to assist ventilation during a respiratory treatment", "Inflate garments on a limb in a cycle to help reduce stasis in the legs", "Apply an abdominal binder to support a surgical wound during recovery from an operation", "Deliver a defibrillation shock through adhesive pads on the chest during a resuscitation"], f: "SCDs inflate garments on a limb in a cycle to help reduce stasis, applying intermittent pneumatic compression, often to the legs. They are not life-support ventilators or defibrillators.", keyTerm: "Inflate garments on a limb in a cycle to help reduce stasis", src: "fda-advice" },
    { id: "cb053", ages: 'both', topic: "function", s: "A warmer or thermal blanket system is used to:", c: ["Manage the air temperature of the entire space", "Manage body temperature for the patient", "Manage the temperature inside a supply cabinet", "Manage the humidity in a device storage closet"], f: "Temperature-management devices manage body temperature for the patient by heating or, in some systems, also cooling under a protocol. Over- or under-heating is a risk, so probes, alarms, and accessories matter.", keyTerm: "Manage body temperature for the patient", src: "fda-advice" },
    { id: "cb054", ages: 'both', topic: "function", s: "A wall suction regulator is used to:", c: ["Control oxygen flow from a wall oxygen source to a patient during therapy", "Control vacuum applied to a suction circuit from the outlet", "Control medical air pressure from a wall air source to a blender", "Generate vacuum locally with an electric pump"], f: "A wall suction regulator is used to control vacuum applied to a suction circuit from the outlet, so the applied vacuum can be set and watched. It does not meter wall oxygen or medical air, and it is not a portable suction pump that makes its own vacuum.", keyTerm: "Control vacuum applied to a suction circuit from the outlet", src: "fda-advice" },
    { id: "cb055", ages: 'both', topic: "function", s: "A fetal monitor typically tracks:", c: ["Adult ECG and NIBP on a cardiac monitor at the point of care", "Heart rate and uterine activity traces on a labor monitor", "Overnight airflow and effort on a sleep-study system in the lab", "Adult telemetry waveforms on a staffed central station"], f: "Fetal monitors record FHR and contractions (TOCO on the abdomen, or intrauterine pressure when indicated) so clinicians can assess well-being in labor or testing. A fetal monitor typically tracks heart rate and uterine activity traces on a labor monitor.", keyTerm: "Heart rate and uterine activity traces on a labor monitor", src: "fda-advice" },
    { id: "cb056", ages: 'both', topic: "function", s: "An anesthesia machine, at a basic level, is used to:", c: ["Circulate blood on a heart-lung machine", "Deliver anesthetic vapor to a breathing circuit", "Replace a required vital-signs monitor for the case", "Deliver vacuum for surgical suction during the case"], f: "An anesthesia machine, at a basic level, is used to deliver anesthetic vapor to a breathing circuit, with a gas mixer, ventilation, monitoring, and scavenger provisions as required. It is not a heart-lung machine, a stand-alone vital-signs monitor, or a suction regulator.", keyTerm: "Deliver anesthetic vapor to a breathing circuit", src: "fda-advice" },
    { id: "cb057", ages: 'both', topic: "function", s: "An external pacemaker (for example a transcutaneous or temporary external unit) is used to:", c: ["Deliver a defibrillation shock for a shockable rhythm", "Deliver pacing pulses through the adhesive pads", "Display pacing from an already implanted generator", "Deliver a synchronized cardioversion for an indicated rhythm"], f: "An external pacemaker, whether transcutaneous or another temporary external unit, is used to deliver pacing pulses through the adhesive pads, or through a pacing lead when that strategy is indicated, under a clinical protocol. Transcutaneous pacing uses large adhesive pads. Other shock therapies and already-present implants are different tools, not this external unit's basic job.", keyTerm: "Deliver pacing pulses through the adhesive pads", src: "fda-advice" },
    { id: "cb058", ages: 'both', topic: "function", s: "A fluid warmer is used in perioperative or emergency care to:", c: ["Warm fluids or blood products held in a storage cabinet", "Warm fluids or blood products during a patient infusion", "Warm blankets or linens in a cabinet for later use", "Warm contrast media for a CT or angiography exam"], f: "Fluid warmers reduce the chance of hypothermia from cold infusions. A fluid warmer is used to warm fluids or blood products during a patient infusion, with the right disposables and temperature limits.", keyTerm: "Warm fluids or blood products during a patient infusion", src: "fda-advice" },
    { id: "cb059", ages: 'both', topic: "function", s: "A spirometer is a diagnostic device used to:", c: ["Document overnight airflow during a sleep study", "Measure lung volumes during a breathing test", "Document hearing thresholds in an audiology booth", "Document visual acuity on an exam-area eye chart"], f: "Spirometry records volumes and flow for pulmonary testing, so it can measure lung volumes during a breathing test. Calibration with a syringe and infection-control practices are typical technical points.", keyTerm: "Measure lung volumes during a breathing test", src: "fda-advice" },
    { id: "cb060", ages: 'both', topic: "function", s: "An otoscope is used to:", c: ["Inspect the retina with a handheld ophthalmoscope", "Look into the ear canal with a lighted instrument", "Take a tympanic temperature with an ear thermometer", "Screen hearing thresholds with a handheld audiometer"], f: "An otoscope is used to look into the ear canal with a lighted instrument, so the canal and eardrum can be seen. Specula, a light source, and sometimes insufflation or a captured image support that exam. Other ear tools measure temperature or hearing, and an ophthalmoscope is used for the eye, not this view of the canal and drum.", keyTerm: "Look into the ear canal with a lighted instrument", src: "fda-advice" },
    { id: "cb061", ages: 'both', topic: "troubleshooting", s: "A monitor is completely dark, and no power light is on. The wall outlet is live. A sound first check looks at:", c: ["The LCD panel, backlight inverter, and video cable, then the display board", "The mains cord, front switch, and inlet fuse, then the supply", "The network drop, IP settings, and interface engine, then the EMR map", "The operating system, user profile, and display driver, then a reimage"], f: "If a monitor is fully dark and the wall outlet is live, start with the mains cord, front switch, and inlet fuse, then the supply. A dark unit with no power light is still a power-path problem until those parts are cleared.", keyTerm: "The mains cord, front switch, and inlet fuse, then the supply", src: "fda-digital" },
    { id: "cb062", ages: 'both', topic: "troubleshooting", s: "A physiologic monitor shows a flat ECG and a 'leads off' message, but a simulator on the same cable is normal. The more likely problem is:", c: ["A failed ECG amplifier on that bedside monitor", "The electrode connection at the patient skin", "A dropped network path to the central station", "A discharged internal battery in the bedside monitor"], f: "If a known source on the same cable is normal, the monitor path can capture that signal. The more likely problem is the electrode connection at the patient skin, including prep and lead wires.", keyTerm: "The electrode connection at the patient skin", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform used as a known test pattern." },
    { id: "cb063", ages: 'both', topic: "troubleshooting", s: "Two work orders arrive at the same time: a ventilator in use on a patient has a critical alarm, and an infusion pump in use on another patient shows a delayed battery-low notice. You should go first to the ventilator for this reason:", c: ["Its work order was entered earlier in the CMMS", "It is in use on a patient with a critical alarm", "The battery-low notice has been on the screen longer", "Both devices share the same default priority code"], f: "Prioritize by risk, urgency, and effect on care. You should go first to the ventilator because it is in use on a patient with a critical alarm. A delayed battery-low notice on another in-use pump is a lower immediate risk. Ticket time, notice duration, or a matching CMMS priority code does not outrank that alarm.", keyTerm: "It is in use on a patient with a critical alarm", src: "fda-vent" },
    { id: "cb064", ages: 'both', topic: "troubleshooting", s: "A nurse reports 'the infusion pump is broken' after a dose was entered incorrectly and the pump alarmed in the expected way. This is best classified as:", c: ["A hardware fault, and send the pump to the shop for bench repair", "A use-related issue, and review the dose entry with the user", "An overdue calibration, and run a full performance verification", "A vendor software defect, and open a ticket for a firmware review"], f: "If a dose was entered incorrectly and the pump alarmed as designed, classify it as a use-related issue, and review the dose entry with the user. Training or a process change may still be needed, but the device did its job. A hardware repair, a full calibration, or a firmware ticket would be a different classification.", keyTerm: "A use-related issue, and review the dose entry with the user", src: "fda-infusion" },
    { id: "cb065", ages: 'both', topic: "troubleshooting", s: "One telemetry transmitter on a hall drops out, but the whole unit's other transmitters are fine. You should first suspect:", c: ["A central-station fault affecting the whole unit", "A fault local to that transmitter serving the unit", "A core-network outage hospital-wide", "A facility-wide telemetry antenna failure"], f: "When only one transmitter drops out and the rest of the unit is fine, first suspect a fault local to that transmitter serving the unit, such as its battery, antenna, or a coverage dead zone. A unit-wide, campus-wide, or building-antenna fault would usually affect more than one transmitter.", keyTerm: "A fault local to that transmitter serving the unit", src: "fda-digital" },
    { id: "cb066", ages: 'both', topic: "troubleshooting", s: "Every telemetry display on a unit fails at once, while other hospital networks still work. That pattern suggests:", c: ["A single transmitter battery fault on one patient", "A shared-system problem on that unit's path", "A campus-wide network collapse across hospital systems", "A failed wall receptacle in a single patient bay"], f: "When every telemetry display on a unit fails at once, while other hospital networks still work, the pattern suggests a shared-system problem on that unit's path, such as an access point or a controller. A single-patient lead or room-outlet fault would not take down every display, and a campus-wide collapse would also affect other networks.", keyTerm: "A shared-system problem on that unit's path", src: "fda-digital" },
    { id: "cb067", ages: 'both', topic: "troubleshooting", s: "A newly installed monitor will not send data to the EMR, but waveforms look correct at the bedside. A useful early step is:", c: ["Recalibrate ECG channels on the new monitor", "Confirm network settings on the new monitor", "Replace the power supply on the new monitor", "Defer the ticket until the next scheduled PM visit"], f: "If a newly installed bedside monitor does not show up at the central station, confirm network settings on the new monitor, including device ID and interface-engine or middleware status. Display and power work at the bedside does not address a missing record in the EMR.", keyTerm: "Confirm network settings on the new monitor", src: "fda-digital" },
    { id: "cb068", ages: 'both', topic: "troubleshooting", s: "A staff member needs a short in-service on a new vital-signs monitor. Your communication should be limited to:", c: ["The manufacturer service manual for bench repair of that vital-signs monitor", "The manufacturer instructions for use (IFU) for that monitor", "The packing slip and invoice that arrived with the new monitor", "A manufacturer training outline from a regional sales visit on that model"], f: "Technicians often give clinicians a short in-service on a new device. Limit that talk to the manufacturer instructions for use (IFU) for that monitor, which is the user-facing document for clinical operation. Repair manuals, packing slips, and sales outlines are written for other purposes and are not a substitute for the IFU.", keyTerm: "The manufacturer instructions for use (IFU) for that monitor", src: "fda-advice" },
    { id: "cb069", ages: 'both', topic: "troubleshooting", s: "A defibrillator fails an energy-output test on a defibrillator analyzer, but the device powers on. The right next path is:", c: ["Recheck that defibrillator with a second analyzer", "Remove that defibrillator from clinical service", "Swap the paddles on that defibrillator", "Report that defibrillator to the manufacturer"], f: "If output energy is outside the allowed error, remove that defibrillator from clinical service and tag it so it cannot be used. Other diagnostic steps can follow, but the unit should not stay available for a case.", keyTerm: "Remove that defibrillator from clinical service", src: "fda-defib" },
    { id: "cb070", ages: 'both', topic: "troubleshooting", s: "An ESU repeatedly faults with a return-electrode alarm. A practical first check looks at:", c: ["The generator power supply, mains cable, and chassis connections", "The return pad, return-pad cable, and pad placement on the patient", "The active electrode, footswitch, and cut-mode settings", "The smoke evacuator hose, filter, and wall suction settings"], f: "A repeated return-electrode alarm is often the pad, cable, or placement. A practical first check looks at the return pad, return-pad cable, and pad placement on the patient, then the generator return circuit if those parts are intact.", keyTerm: "The return pad, return-pad cable, and pad placement on the patient", src: "fda-advice" },
    { id: "cb071", ages: 'both', topic: "troubleshooting", s: "A syringe pump stops and reports occlusion. A sound first set of checks is:", c: ["Recalibrate the occlusion-pressure sensor on the bench", "Check the tubing path at the bedside before the pump", "Install a new syringe at the current rate", "Send the pump for a complete mechanical overhaul"], f: "For an occlusion alarm, check the tubing path at the bedside before the pump, including clamps and position. Recalibration, a new syringe, or a shop overhaul comes after those bedside checks.", keyTerm: "Check the tubing path at the bedside before the pump", src: "fda-infusion" },
    { id: "cb072", ages: 'both', topic: "troubleshooting", s: "A PCA pump can be started, but the lockout interval does not match the order. After confirming the order, you should:", c: ["Re-enter the lockout from a typical unit protocol", "Treat it as a programming problem on that pump", "Power-cycle the pump to clear a temporary display fault", "Hold the pump for a future software update"], f: "A lockout that does not match the prescribed program is a safety issue. Treat it as a programming problem on that pump, and keep the pump unused until the setting is corrected through the proper clinical and technical process.", keyTerm: "Treat it as a programming problem on that pump", src: "fda-infusion" },
    { id: "cb073", ages: 'both', topic: "troubleshooting", s: "A feeding pump free-flows when the door is open and no set is loaded correctly. You should:", c: ["Request a new label on the feeding pump", "Remove the feeding pump from clinical use", "Set the feeding pump aside for later visual review", "Complete a short walk-around inspection of the feeding pump"], f: "Free-flow of enteral or IV fluid when the set is not properly engaged is a serious hazard. You should remove the feeding pump from clinical use and keep it out until a repair is completed. Cosmetic labels or a brief visual look do not correct the fault.", keyTerm: "Remove the feeding pump from clinical use", src: "fda-advice" },
    { id: "cb074", ages: 'both', topic: "troubleshooting", s: "A laboratory centrifuge will not start. The lid interlock still reads open even though the lid is shut. A likely cause is:", c: ["A motor fault on that centrifuge", "A lid-switch fault on that centrifuge", "A selected-speed error on that centrifuge after the lid is shut", "A worn drive belt on that centrifuge"], f: "If the lid interlock still reads open when the lid is shut, a lid-switch fault on that centrifuge, including a latch or interlock problem, is the more likely path. Drive and speed problems usually show up after the lid is already recognized as closed.", keyTerm: "A lid-switch fault on that centrifuge", src: "fda-advice" },
    { id: "cb075", ages: 'both', topic: "troubleshooting", s: "A lab refrigerator used for reagents is at 12 C, above its set range, and the warning did not call. You should:", c: ["Complete a stock inventory of the reagents in the box", "Take the box out of service until cooling is restored", "Adjust the temperature setpoint on the same box", "Schedule a refrigeration PM for the next day's list"], f: "Out-of-range storage can ruin reagents or samples. Take the box out of service until cooling is restored, after protecting the contents, and find why cooling and the alarm both failed. Do not silence alarms to hide the problem.", keyTerm: "Take the box out of service until cooling is restored", src: "fda-advice" },
    { id: "cb076", ages: 'both', topic: "troubleshooting", s: "An otoscope light is dim. The handle has fresh batteries. A simple next check looks at:", c: ["The charging base used with that handle", "The lamp assembly inside that same handle", "A deferred electrical safety test of the handle", "The wall transformer output in that exam area"], f: "With fresh batteries already in the handle, a simple next check looks at the lamp assembly inside that same handle, along with contacts and the head connection, where the remaining light path still lives. The charger is not in that path once the batteries are fresh.", keyTerm: "The lamp assembly inside that same handle", src: "fda-advice" },
    { id: "cb077", ages: 'both', topic: "troubleshooting", s: "A scale used for medication dosing reads 0.4 kg high on a known test weight. You should:", c: ["Post a 0.4 kg correction factor on the dosing scale", "Remove the scale from clinical dosing use", "Wait for the upcoming scheduled calibration cycle", "Add a journal note about the 0.4 kg error"], f: "A dosing scale that fails a known test weight should be removed from clinical dosing use until it is calibrated or replaced and documented. A posted correction factor, a delay until the next cycle, or a journal note alone leaves an inaccurate scale available for dosing.", keyTerm: "from clinical dosing use", src: "fda-advice" },
    { id: "cb078", ages: 'both', topic: "troubleshooting", s: "A stress-test ECG is noisy only when the treadmill is running. A useful direction is:", c: ["Increase the ECG waveform gain during the walk", "Look for interference from the treadmill drive", "Reinstall the analysis application on the computer", "Replace the exam-area lighting for the study"], f: "If the ECG is noisy only when the treadmill is running, look for interference from the treadmill drive, including motion, cable routing, or grounding, because the artifact tracks that source. Raising gain, changing software, or replacing lights first does not find that motion or EMI path.", keyTerm: "Look for interference from the treadmill drive", src: "fda-advice" },
    { id: "cb079", ages: 'both', topic: "troubleshooting", s: "An ultrasound unit powers on but shows no image, and a known-good probe on that connector is also dark. The fault is more likely:", c: ["A failed probe on the last connector used", "A fault in the imaging chain of the unit", "A keyboard fault on the ultrasound console", "A printer fault on the imaging network"], f: "If a known-good probe on that connector is also dark, the fault is more likely a fault in the imaging chain of the unit. A keyboard or archive issue would not usually blank the live image from two probes.", keyTerm: "A fault in the imaging chain of the unit", src: "fda-ultrasound" },
    { id: "cb080", ages: 'both', topic: "troubleshooting", s: "A pulse-oximeter reading is blank on a patient with cold fingers, but a simulator at the same cable reads 98%. This suggests:", c: ["An alarm-limit setting on the pulse oximeter", "A poor peripheral signal at the sensor site", "A probe-cable fault in the monitor path", "A power-supply fault inside the pulse oximeter itself"], f: "A simulator isolates the device and cable. A good simulator reading with a bad patient waveform points to a poor peripheral signal at the sensor site. Cold fingers, placement, or ambient light may be the cause, which clinicians may address. Still treat alarms seriously.", keyTerm: "A poor peripheral signal at the sensor site", src: "fda-pulseox" },
    { id: "cb081", ages: 'both', topic: "troubleshooting", s: "A ventilator in the shop fails a volume check on a test lung, outside its allowed error. You should:", c: ["Complete a walk-around inspection of the display", "Keep it out of service until a passing verification is done", "Hold it for the upcoming scheduled PM visit", "Schedule a power-on self-test for the next shift"], f: "Life-support equipment that fails a performance test stays out of service until it is corrected and verified. Keep it out of service until a passing verification is done, after repair or escalation as needed. Do not pass it by changing limits without authority.", keyTerm: "Keep it out of service until a passing verification is done", src: "fda-vent" },
    { id: "cb082", ages: 'both', topic: "troubleshooting", s: "A balloon pump (IABP) in use has a gas-loss alarm. Your first priority is:", c: ["Stay with the clinical team at the bedside, then open a loaner request from the loaner pool for a replacement pump", "Stay with the clinical team at the bedside, then follow the emergency procedure for the device", "Stay with the clinical team at the bedside, then complete the incident paperwork", "Stay with the clinical team at the bedside, then call materials for a replacement part"], f: "A gas-loss alarm on an IABP in use is an emergency at the bedside. Your first priority is to stay with the clinical team at the bedside, then follow the emergency procedure for the device.", keyTerm: "then follow the emergency procedure for the device", src: "fda-advice" },
    { id: "cb083", ages: 'both', topic: "troubleshooting", s: "An anesthesia machine fails a pre-use leak test. The correct action is:", c: ["Leave it out of use until the coming change of personnel", "Leave it out of use until a passing verification is done", "Leave it out of use until a unit log entry is written", "Return it after a walk-around check of the machine"], f: "A failed pre-use leak test means the machine is not ready. Leave it out of use until a passing verification is done, after the leak is found and corrected.", keyTerm: "Leave it out of use until a passing verification is done", src: "fda-advice" },
    { id: "cb084", ages: 'both', topic: "troubleshooting", s: "A surgical table will not unlock to reposition, and the patient is on the table. You should:", c: ["Arrange a transfer to another table first", "Use the emergency release provided on the table", "Wait for a loaner table from central supply", "Call the equipment help desk for further instructions"], f: "With a patient on the table, an emergency release comes first. Use the emergency release provided on the table. Waiting for another table or for outside instructions delays that release. Do not improvise with force that could injure the patient or wreck the table.", keyTerm: "Use the emergency release provided on the table", src: "fda-advice" },
    { id: "cb085", ages: 'both', topic: "troubleshooting", s: "An infant warmer's skin-temperature probe is off the skin, and the unit is in servo mode. The unsafe pattern to watch for is:", c: ["Heater overshoot from a failed over-temperature cutoff", "Heater overshoot with no true skin-temperature input", "Heater overshoot from a stored probe-file temperature", "Heater overshoot from a water-bath temperature setting"], f: "In servo (skin) mode the heater is driven by the probe. A loose or detached probe can lead to overheating because the unit no longer sees a true skin temperature. The pattern to watch for is heater overshoot with no true skin-temperature input. Check probe placement and mode, and follow the device's alarm behavior.", keyTerm: "Heater overshoot with no true skin-temperature input", src: "fda-advice" },
    { id: "cb086", ages: 'both', topic: "troubleshooting", s: "A therapeutic ultrasound unit in physical therapy has a worn sound head and a failed completeness-of-output check. You should:", c: ["Post a door sign for the treatment room", "Stop treatments until a passing output test is done", "Log a timer check as the output verification", "Schedule a deferred output check for the next week"], f: "If the sound head is worn and output cannot be verified, stop treatments until a passing output test is done, after the applicator is corrected. A posted sign, a timer check, or a later test after booking more patients is not enough.", keyTerm: "Stop treatments until a passing output test is done", src: "fda-ultrasound" },
    { id: "cb087", ages: 'both', topic: "troubleshooting", s: "A video integration system in an OR has no image on the main display, but the endoscope's local screen works. A useful path is:", c: ["Recalibrate the endoscope on the video tower", "Trace the signal route to the main display", "Reboot the recording PC used for image capture", "Adjust the overhead lighting for the main display"], f: "If the endoscope's local screen works, the scope is producing a picture. A useful path is to trace the signal route to the main display, including cables and any switcher. Work on the scope, the recorder, or room lights does not find a break in that path.", keyTerm: "Trace the signal route to the main display", src: "fda-advice" },
    { id: "cb088", ages: 'both', topic: "troubleshooting", s: "A circulating nurse says a newly installed device does not work the way the previous unit did. The best first technical step is:", c: ["Compare the new unit to a wall sign about the previous model", "Confirm settings on the new unit against the manual", "Look up a prior staff complaint ticket for saved settings", "Copy the setup from the loaner identification tag"], f: "When a newly installed device does not behave as staff expect, confirm settings on the new unit against the manual, after asking what was expected, and compare to a known-good unit. Hallway signs, old complaint tickets, or loaner paperwork are weaker first sources.", keyTerm: "Confirm settings on the new unit against the manual", src: "fda-advice" },
    { id: "cb089", ages: 'both', topic: "troubleshooting", s: "A module in a physiologic monitor loses only the IBP channel, while ECG and NIBP still work. That pattern suggests:", c: ["A printer fault on the physiologic monitor", "A local fault in that pressure channel path", "A complete main-board failure on the physiologic monitor", "A power-supply fault affecting the full set of channels"], f: "If only the IBP channel is lost while ECG and NIBP still work, the pattern suggests a local fault in that pressure channel path, including its cable or transducer interface. A printer, full main-board, or supply failure would usually affect more than one channel.", keyTerm: "A local fault in that pressure channel path", src: "fda-advice" },
    { id: "cb090", ages: 'both', topic: "troubleshooting", s: "You finish a repair on a life-support device. Before it returns to service you should:", c: ["Power the device on for a short bench note", "Test the functions that were affected after the repair", "Update the upcoming PM date in the CMMS", "Attach a return tag for a clinical trial on the unit"], f: "After a life-support repair, test the functions that were affected after the repair, and complete the required documentation, before a return to service. A power-on note, a CMMS date change, or a clinical trial on the unit is not enough by itself.", keyTerm: "Test the functions that were affected after the repair", src: "fda-advice" },
    { id: "cb091", ages: 'both', topic: "safety", s: "A protective earth (ground) conductor on a medical device power cord is there mainly to:", c: ["Carry the normal operating current as the chassis return", "Carry a low-impedance fault current for protective operation", "Hold the device at earth potential during normal operation", "Isolate the chassis from earth so fault current cannot flow"], f: "The grounding conductor is a safety path for fault current. A protective earth conductor is there mainly to carry a low-impedance fault current for protective operation, so touch voltage stays low. NFPA 99 and IEC 60601 address grounding and leakage in healthcare electrical systems and equipment; consult those standards for limits and methods.", keyTerm: "Carry a low-impedance fault current for protective operation", src: "iec-60601", also: ["nfpa-99"], img: "img/cbet-plug.svg", imgAlt: "Front view of a US NEMA 5-15 receptacle with the ground hole down: the wider neutral slot is on the left, the narrower hot slot is on the right, and the ground hole is at the bottom.", imgAsk: true },
    { id: "cb092", ages: 'both', topic: "safety", s: "Macroshock and microshock are different in this way:", c: ["Microshock concerns the voltage level in that model", "Microshock concerns small currents that can reach the heart", "Microshock concerns currents that travel across intact dry skin", "Microshock concerns currents that stay on the equipment chassis"], f: "Macroshock is a shock through the intact body. Microshock concerns small currents that can reach the heart through a conductive path, for example a catheter or lead. Design and testing of patient connections take that risk into account. See IEC 60601 and NFPA 99 for the official limits and tests.", keyTerm: "Microshock concerns small currents that can reach the heart", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb093", ages: 'both', topic: "safety", s: "A GFCI device is intended to:", c: ["Open the circuit when equipment-ground current is the trip signal", "Open the circuit when it detects a dangerous imbalance between hot and neutral", "Open the circuit when it detects a dangerous overvoltage on the hot and neutral lines", "Open the circuit when it detects a dangerous overload on the hot and neutral lines"], f: "A GFCI compares current in the ungrounded (hot) conductor with current in the grounded (neutral) conductor and opens if they differ by more than a trip threshold, which can mean current is leaving the intended circuit. In short, it is intended to open the circuit when it detects a dangerous imbalance between hot and neutral. It is not a surge protector or an overcurrent breaker.", keyTerm: "imbalance between hot and neutral", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb094", ages: 'both', topic: "safety", s: "A Safety Data Sheet (SDS) is used to:", c: ["List catalog numbers, vendors, and reorder points for a product", "Describe chemical hazards, PPE, and emergency actions for a product", "Store a patient's medications, allergies, and pharmacy notes in the chart", "Store default settings, options, and a repair note for a device"], f: "The SDS (formerly MSDS) is used to describe chemical hazards, PPE, and emergency actions for a product, along with storage information. It is not a medical record, a purchasing catalog, or a device setting sheet.", keyTerm: "Describe chemical hazards, PPE, and emergency actions for a product", src: "osha-elec", also: ["nfpa-99"] },
    { id: "cb095", ages: 'both', topic: "safety", s: "A standard ionizing-radiation trefoil warning sign is meant to:", c: ["Warn of a magnetic-field hazard in that area or on that source", "Warn of a radiation hazard in that area or on that source", "Warn of a visible-laser hazard in that area or on that source", "Warn of a biological hazard in that area or on that source"], f: "A standard ionizing-radiation trefoil sign is meant to warn of a radiation hazard in that area or on that source, so people can follow the controls posted there. The trefoil is not a magnet, laser, or biohazard symbol.", keyTerm: "Warn of a radiation hazard in that area or on that source", src: "nfpa-99" },
    { id: "cb096", ages: 'both', topic: "safety", s: "Standard precautions in a healthcare facility include:", c: ["Hand hygiene at the start of the shift as the main control", "Hand hygiene plus the PPE required for the task", "Hand hygiene at the end of the shift as the main control", "Hand hygiene reserved for documented isolation rooms"], f: "Standard precautions assume that blood and body fluids may be infectious. Hand hygiene plus the PPE required for the task is the core practice, treating body fluids as potentially infectious, with safe sharps handling and cleaning, as taught by CDC and required in facilities.", keyTerm: "Hand hygiene plus the PPE required for the task", src: "cdc-precautions", also: ["nfpa-99"] },
    { id: "cb097", ages: 'both', topic: "function", s: "CMS (Centers for Medicare and Medicaid Services) is important to hospitals for this reason:", c: ["It issues state professional-engineer licenses for hospital staff", "It sets Conditions of Participation for hospital programs", "It licenses medical-device manufacturers under a 510(k) program", "It writes local fire-evacuation maps for each hospital campus"], f: "CMS is important to hospitals because it sets Conditions of Participation for hospital programs and recognizes accrediting organizations. Those conditions are a major reason hospitals maintain accredited safety and equipment programs.", keyTerm: "It sets Conditions of Participation for hospital programs", src: "cms-cops", also: ["nfpa-99"] },
    { id: "cb098", ages: 'both', topic: "safety", s: "Under IEC 60601-1, which applied-part type has the tightest patient leakage current limits?", c: ["Type B, for general body applied parts in non-cardiac contact", "Type CF, for direct cardiac applied parts", "Type BF, for body-floating applied parts", "Type AF, for general body applied parts"], f: "Type CF applied parts, intended for direct cardiac connection, have tighter patient-leakage limits than type B or BF in IEC 60601-1, in both normal and single-fault condition. Typical teaching values are on the order of 10 microamps for CF in normal condition, versus on the order of 100 microamps for B or BF. Confirm the figures in the current edition of the standard and on the device labeling. The tightest class is Type CF, for direct cardiac applied parts.", keyTerm: "Type CF, for direct cardiac applied parts", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb099", ages: 'both', topic: "safety", s: "For a given applied-part type, IEC 60601-1 leakage current limits in single-fault condition, compared with normal condition, are:", c: ["The same numerical limit as in normal condition", "A higher official limit than in normal condition", "Dropped as a requirement under the standard", "Replaced by a manufacturer design target"], f: "The standard allows a higher leakage current in a specified single-fault condition than in normal condition, but the current is still capped. Limits are a higher official limit than in normal condition. Type CF remains tighter than type BF in both conditions. Use the values and test setup from the edition and labeling that apply.", keyTerm: "A higher official limit than in normal condition", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb100", ages: 'both', topic: "safety", s: "An MRI warning sign is posted for this reason:", c: ["The strong magnetic field can interfere with nearby Wi-Fi links", "The strong magnetic field pulls ferromagnetic objects", "The strong magnetic field is mainly a noise-reduction benefit", "The strong magnetic field is mainly a wayfinding cue for visitors"], f: "MRI systems have a strong magnetic field that pulls ferromagnetic objects, creating a serious projectile hazard, along with other hazards such as implants and time-varying fields. Access and screening rules exist to prevent projectile and implant injuries.", keyTerm: "pulls ferromagnetic objects", src: "nfpa-99" },
  ]
});
